glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);

  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;

  gl_Position = pos;
}

glsl3.frag:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform sampler2D noiseTex;
uniform sampler2D maskTex;

uniform PROPERTIES {
  float noiseIntensity;
  float noiseSpeedX;
  float noiseSpeedY;
  float time;
  float running;
  float rate;
};

float random (in vec2 st) { 
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123); 
}

vec2 getOffsetFromNoiseTex(vec2 uv) {
  float x = fract(uv.x);
  float y = fract(uv.y);
  vec4 color = texture2D(noiseTex, vec2(x, y));
  color = (color * 2.0 - 1.0) * 0.1;
  return color.xy;
}

vec2 disturbance(vec4 mask) {

    float ifY_0_3 = step(0.3, v_uv0.y); 
    float ifX_0_4 = step(0.4, v_uv0.x);

    float dirx = 1.0 - ifY_0_3 - ifX_0_4 * ifY_0_3;
    float diry = 1.0 - 2.0 * ifY_0_3;
    float interrate = 1.0 - 0.5 * ifY_0_3 * ifX_0_4;
    float speedrate = 0.8 - 0.2 * ifY_0_3;

    float t = (time + cc_time.x) * rate * 2.0;
    vec2 timer = vec2(t * dirx * noiseSpeedX, t * diry * noiseSpeedY) * speedrate;
    vec2 offset = getOffsetFromNoiseTex(v_uv0 + timer) * running;
    return v_uv0 + offset * noiseIntensity * interrate * mask.r;

}

vec4 highlight(vec4 color, vec4 mask) {
  float strength = 0.4;
  float t = (time + cc_time.x) * rate;
  return vec4(color.rgb + vec3(1.0, 1.0, 1.0) * strength * (sin(t*25.0) * 0.5 + 1.0) * mask.g, color.a);
}

void main () {
  vec4 mask = texture2D(maskTex, v_uv0);
  vec2 uv = disturbance(mask);
  vec4 texColor = texture2D(texture, uv);
  vec4 finalColor = highlight(texColor, mask);
  vec4 o = v_color * finalColor;
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

